@_documentation(visibility: private)
#endif
public struct FfiConverterTypeAllDayBar: FfiConverterRustBuffer {
    public static func read(from buf: inout (data: Data, offset: Data.Index)) throws -> AllDayBar {
        return
            try AllDayBar(
                pageId: FfiConverterString.read(from: &buf), 
                startCol: FfiConverterUInt32.read(from: &buf), 
                span: FfiConverterUInt32.read(from: &buf), 
                row: FfiConverterUInt32.read(from: &buf), 
                continuesLeft: FfiConverterBool.read(from: &buf), 
                continuesRight: FfiConverterBool.read(from: &buf)
        )
    }

    public static func write(_ value: AllDayBar, into buf: inout [UInt8]) {
