        FfiConverterUInt32.write(value.span, into: &buf)
        FfiConverterUInt32.write(value.row, into: &buf)
        FfiConverterBool.write(value.continuesLeft, into: &buf)
        FfiConverterBool.write(value.continuesRight, into: &buf)
    }
}


