/**
 * One thing for the calendar to draw.
 *
 * Flattened on purpose. A recurring page is stored once — a head row plus a
 * rule — and its other occurrences are projected at display time rather than
 * written out, so the calendar's input is not "the pages in this range": it is
 * the pages *plus* whatever the rules project onto it. Working that out needs
 * three queries and a merge, and doing it in Swift would mean reimplementing
 * the desktop's `useRecurrenceExpansion` a second time, in a second language,
 * with no way to grade it. `Workspace::calendar_range` does it once.
 */
public struct CalendarEntry: Equatable, Hashable {
    public var pageId: String
    /**
     * Distinct per drawn item — the page id for a real block, and the page id
     * plus the occurrence's date for a projected one. `page_id` is *not*
     * unique here: a weekly series appears several times in a week and every
     * one of those carries the same page id, deliberately (see
     * `pikos_core::calendar::occurrences`).
     */
    public var key: String
    public var title: String
    public var status: String
    public var priority: Int64
    public var folderId: String?
    public var tags: [String]
    /**
     * Tiebreaker for equal-length all-day spans, and nothing else.
     */
    public var createdAt: String
    public var scheduledStart: String
    public var scheduledEnd: String?
    /**
     * Projected from a recurrence rule: there is no row behind it, so editing
     * it has to materialise one first.
     */
    public var isVirtual: Bool
    /**
     * The rule's own date for this occurrence, which is how a skip or an
     * override is matched back to it. `None` on a real block.
     */
    public var originalDate: String?
    /**
     * The page behind this block repeats — so the block is one occurrence of a
     * series rather than the whole of anything.
     *
     * Not the same question as `is_virtual`, and the difference is what makes
     * this field necessary. A repeating page's *own* row is a real block with
     * no `original_date`, and it is the one most often on screen: this week's
     * standup, drawn from the head. Treating it as a one-off is how "delete
     * this occurrence" becomes "delete the series".
     */
    public var isRecurring: Bool
    /**
     * The page came from a calendar, whether or not it is still mirrored.
     *
     * Sync *origin*, deliberately, and not "is locked": a detached series is
     * unlocked and still an imported calendar. The desktop draws a checkbox on
     * an occurrence of a synced-origin series and not on one of a native
     * series, because the two mean different things — a birthday is resolved
     * on the day it names, while a task series funnels to whichever occurrence
     * is next due. Without this field the phone cannot tell them apart, and
     * would offer to complete a native occurrence three weeks out.
     */
    public var isSyncedOrigin: Bool
    /**
     * The rule that projected this block, for the operations keyed on the
     * rule rather than on the page — moving one occurrence out of the series.
     * `None` on a real block, which has a row of its own to move instead.
     */
    public var ruleId: String?
    /**
     * A calendar owns this page's schedule, so its times are not ours to
     * change. The workspace refuses such a move anyway; this is what lets the
     * menu leave the entry out rather than offer it and fail.
     */
    public var scheduleLocked: Bool

    // Default memberwise initializers are never public by default, so we
    // declare one manually.
    public init(pageId: String, 
        /**
         * Distinct per drawn item — the page id for a real block, and the page id
         * plus the occurrence's date for a projected one. `page_id` is *not*
         * unique here: a weekly series appears several times in a week and every
         * one of those carries the same page id, deliberately (see
         * `pikos_core::calendar::occurrences`).
         */key: String, title: String, status: String, priority: Int64, folderId: String?, tags: [String], 
        /**
         * Tiebreaker for equal-length all-day spans, and nothing else.
         */createdAt: String, scheduledStart: String, scheduledEnd: String?, 
        /**
         * Projected from a recurrence rule: there is no row behind it, so editing
         * it has to materialise one first.
         */isVirtual: Bool, 
        /**
         * The rule's own date for this occurrence, which is how a skip or an
         * override is matched back to it. `None` on a real block.
         */originalDate: String?, 
        /**
         * The page behind this block repeats — so the block is one occurrence of a
         * series rather than the whole of anything.
         *
         * Not the same question as `is_virtual`, and the difference is what makes
         * this field necessary. A repeating page's *own* row is a real block with
         * no `original_date`, and it is the one most often on screen: this week's
         * standup, drawn from the head. Treating it as a one-off is how "delete
         * this occurrence" becomes "delete the series".
         */isRecurring: Bool, 
        /**
         * The page came from a calendar, whether or not it is still mirrored.
         *
         * Sync *origin*, deliberately, and not "is locked": a detached series is
         * unlocked and still an imported calendar. The desktop draws a checkbox on
         * an occurrence of a synced-origin series and not on one of a native
         * series, because the two mean different things — a birthday is resolved
         * on the day it names, while a task series funnels to whichever occurrence
         * is next due. Without this field the phone cannot tell them apart, and
         * would offer to complete a native occurrence three weeks out.
         */isSyncedOrigin: Bool, 
        /**
         * The rule that projected this block, for the operations keyed on the
         * rule rather than on the page — moving one occurrence out of the series.
         * `None` on a real block, which has a row of its own to move instead.
         */ruleId: String?, 
        /**
         * A calendar owns this page's schedule, so its times are not ours to
         * change. The workspace refuses such a move anyway; this is what lets the
         * menu leave the entry out rather than offer it and fail.
         */scheduleLocked: Bool) {
        self.pageId = pageId
